-- Q12273: Financial Reporting: For-Profit [medium/L3]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["As an expense deducted before arriving at consolidated net income on the income statement","As an allocation below consolidated net income showing the parent''s attributable amount separately","In other comprehensive income as a separate equity component of the consolidated statements","As a separate line item presented within the operating expenses section of the statement"]$EXPL$::jsonb,
